REVOKE INSERT ON public.project_duplication_requests FROM authenticated;
GRANT INSERT (brand_id, source_project_id, created_by, request_id) ON public.project_duplication_requests TO authenticated;
DROP POLICY "duplication requests own insert" ON public.project_duplication_requests;
CREATE POLICY "duplication requests own insert" ON public.project_duplication_requests FOR INSERT TO authenticated WITH CHECK (created_by=auth.uid() AND duplicated_project_id IS NULL AND public.can_access_project(source_project_id,auth.uid()) AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id=source_project_id AND p.brand_id=project_duplication_requests.brand_id AND public.is_agency_operator(auth.uid(),project_duplication_requests.brand_id)));
DROP POLICY "duplication requests own completion" ON public.project_duplication_requests;
CREATE POLICY "duplication requests own completion" ON public.project_duplication_requests FOR UPDATE TO authenticated USING (created_by=auth.uid() AND duplicated_project_id IS NULL AND public.can_access_project(source_project_id,auth.uid())) WITH CHECK (created_by=auth.uid() AND duplicated_project_id IS NOT NULL AND public.can_access_project(source_project_id,auth.uid()) AND EXISTS (SELECT 1 FROM public.projects source JOIN public.projects copied ON copied.id=project_duplication_requests.duplicated_project_id WHERE source.id=project_duplication_requests.source_project_id AND source.brand_id=project_duplication_requests.brand_id AND copied.brand_id=project_duplication_requests.brand_id AND copied.client_id IS NOT DISTINCT FROM source.client_id AND public.can_access_project(copied.id,auth.uid())));